package com.example.shop.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import lombok.Data;
import java.lang.Long;
import java.lang.String;

@Entity
@Data
public class Widget {

    @Id
    private Long id;

    @Column(name = "label")
    private String label;
}
